// O broker pode ser público: só aceita mensagens do dispositivo configurado.
const dispositivo = env.get('SAMPAIA_DISPOSITIVO');
const [, disp, acao] = msg.topic.split('/');
if (!dispositivo || disp !== dispositivo) return null;

if (acao === 'status') {
    node.status({ fill: msg.payload === 'online' ? 'green' : 'grey', shape: 'dot', text: `ESP32 ${msg.payload}` });
    return null;
}
if (acao === 'pedir') return [msg, null];
if (acao === 'concluir') {
    const id = Number(msg.payload && msg.payload.id);
    if (!Number.isInteger(id) || id <= 0) { node.warn('concluir sem id válido'); return null; }
    return [null, { id }];
}
return null; // 'lembrete' é o que nós mesmos publicamos

// 204 = nada vencendo. Erro: não publica nada (o ESP32 mantém o último retido).
let lembrete;
if (msg.statusCode === 204) {
    lembrete = { id: -1 };
} else if (msg.statusCode === 200 && msg.payload && typeof msg.payload === 'object') {
    const p = msg.payload;
    lembrete = { id: p.id, titulo: p.titulo, dias: p.dias, alerta: !!p.alerta };
} else {
    node.status({ fill: 'red', shape: 'ring', text: `API respondeu ${msg.statusCode}` });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: lembrete.id > 0 ? `${lembrete.titulo}: ${lembrete.dias} dia(s)` : 'nada vencendo' });
return { topic: `sampaia/${env.get('SAMPAIA_DISPOSITIVO')}/lembrete`, payload: lembrete };

msg.method = 'POST';
msg.url = `${env.get('LEMBRETES_URL')}/api/lembretes/${msg.id}/concluir`;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {};
return msg;
